"""
    Generates lua lines that One-Hot encodes a field from its possible options

    :param input_field: original censys field
    :param output_field: flattened version of censys field
    :param options: array of the possible values the input field can have
    :param function_name: the lua function that will encode the field
    :param field_prefix: an optional string to be concatenated at the end of original field
    :return:
    """
def one_hot_encode(
    input_field: Any,
    output_field: Any,
    options: Any,
    function_name: Any,
    field_prefix: Any = ""
) -> object {
    lines = [];
    for option in options {
        key = option;
        if (`type(option) == str) {
            key = f'"{option}"';
        }
        lines.append(
            f'event["{output_field}_{field_prefix}{option}"] = {function_name}(event["{input_field}"])[{key}]'
        );
    }
    return lines;
}

"""Conversion from rgba to ycc.

    Notes:
         Expects and returns values in [0,255] range.
    """
def _ycc(r: Any, g: Any, b: Any, a: Any = None) -> object {
    y = (0.299 * r) + (0.587 * g) + (0.114 * b);
    cb = (128 - (0.168736 * r) - (0.331364 * g)) + (0.5 * b);
    cr = (128 + (0.5 * r)) - (0.418688 * g) - (0.081312 * b);
    if (a is not None) {
        return [y, cb, cr, a];
    } else {
        return [y, cb, cr];
    }
}

"""
    Prepends some magic data to a filename in order to have long filenames.

    .. warning:: This might be Windows specific.
    """
def _filename(filename: str) -> str {
    if (len(filename) > 255) {
        return ('\\\\?\\' + filename);
    }
    return filename;
}

"""
    >>> is_in_list(5, [1, 2, 3, 4])
    False
    >>> is_in_list(5, [1, 5, 6])
    True
    """
def is_in_list(num: Any, lst: Any) -> object {
    in_list = False;
    for item in lst {
        if (num == item) {
            in_list = True;
            break;
        }
    }
    return in_list;
}
